/**
 * ═══════════════════════════════════════════════════════════════════════════
 * Draft Run Controller
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * Endpoints that operate on draft test runs (ephemeral steps generated by the
 * AI agent in editor mode and cached in DraftStepsCache).
 *
 * Currently exposes one endpoint:
 * - POST /api/v1/preview/draft/save-as-test-case
 *     Persist the cached draft steps as a real intent_test_case in the DB.
 *     Used by the universal Quick Action framework — see
 *     src/api/preview/quick-action-endpoints.ts for the whitelist entry.
 *
 * Why a separate controller (instead of growing preview.controller.ts):
 * - This file owns the cache→DB migration logic and the name resolution
 *   waterfall (override → AI suggested → first navigate URL → default).
 *   Keeping it isolated makes both easy to test and to extend with future
 *   draft-related actions (re-run, discard, edit-and-save, etc.).
 *
 * ═══════════════════════════════════════════════════════════════════════════
 */

import { Request, Response } from 'express';
import { logger } from '@/utils/core/logger';
import { getPreviewSessionService } from '@/services/testing/ui/preview/preview-session.service';
import { DraftStepsCache } from '@/services/testing/ui/preview/draft-steps-cache';
import { IntentTestCaseService } from '@/services/testing/ui/preview/intent-test-case.service';
import type { IntentStep } from '@/services/testing/ui/preview/preview.types';

// ─────────────────────────────────────────────────────────────────────────
// Name resolution waterfall
// ─────────────────────────────────────────────────────────────────────────

/**
 * Try to derive a human-readable test case name from the steps themselves.
 * Used as the third tier of the resolution waterfall when neither the user
 * nor the AI provided a name.
 *
 * Heuristics (in order):
 *  1. First `navigate` step → `Test for /<pathname>`
 *  2. First step with a meaningful description → first 50 chars
 *  3. Default → `Untitled draft test (N steps)`
 */
function deriveNameFromSteps(steps: IntentStep[]): string {
  // 1. Pull pathname from the first navigate step
  const navigateStep = steps.find(s => s.type === 'navigate' && (s.value || s.description));
  if (navigateStep) {
    const target = navigateStep.value || navigateStep.description || '';
    try {
      // value is usually a full URL, description sometimes is too
      const urlMatch = target.match(/https?:\/\/[^\s]+/);
      if (urlMatch) {
        const url = new URL(urlMatch[0]);
        const path = url.pathname.replace(/\/+$/, '') || '/';
        return `Test for ${path}`;
      }
    } catch {
      // Not a URL — fall through to description
    }
    // Fall back to first 50 chars of the description
    const trimmed = (navigateStep.description || '').trim().slice(0, 50);
    if (trimmed) return `Test for ${trimmed}`;
  }

  // 2. First descriptive step
  const firstDescriptive = steps.find(s => typeof s.description === 'string' && s.description.trim().length > 0);
  if (firstDescriptive?.description) {
    const sliced = firstDescriptive.description.trim().slice(0, 50);
    return sliced.charAt(0).toUpperCase() + sliced.slice(1);
  }

  // 3. Default
  return `Untitled draft test (${steps.length} step${steps.length === 1 ? '' : 's'})`;
}

/**
 * Resolve the final test case name from the available sources, in order of
 * priority. Each source can be undefined; the waterfall always terminates
 * with a deterministic default.
 */
function resolveTestCaseName(
  nameOverride: string | undefined,
  suggestedName: string | undefined,
  steps: IntentStep[],
): string {
  if (typeof nameOverride === 'string') {
    const trimmed = nameOverride.trim();
    if (trimmed) return trimmed.slice(0, 200);
  }
  if (typeof suggestedName === 'string') {
    const trimmed = suggestedName.trim();
    if (trimmed) return trimmed.slice(0, 200);
  }
  return deriveNameFromSteps(steps);
}

// ─────────────────────────────────────────────────────────────────────────
// Endpoint
// ─────────────────────────────────────────────────────────────────────────

/**
 * POST /api/v1/preview/draft/save-as-test-case
 *
 * Body:
 *   {
 *     previewSessionId: string  // required — owned by the caller
 *     chatSessionId:    string  // required — key under which steps are cached
 *     nameOverride?:    string  // optional — user-typed name (highest priority)
 *   }
 *
 * Response (success):
 *   {
 *     success: true,
 *     testCase: { id, name }
 *   }
 *
 * Errors:
 *   400 — missing fields, no cached steps
 *   401 — unauthenticated
 *   403 — preview session not owned by caller, or cached steps belong to a
 *         different user
 *   404 — preview session does not exist
 *   500 — IntentTestCaseService failure (cache is NOT cleared so user can retry)
 */
export async function saveDraftRunAsTestCase(req: Request, res: Response): Promise<void> {
  try {
    const userId = (req as any).user?.id as string | undefined;
    if (!userId) {
      res.status(401).json({ success: false, error: 'Unauthorized' });
      return;
    }

    const { previewSessionId, chatSessionId, nameOverride } = req.body || {};

    if (typeof previewSessionId !== 'string' || !previewSessionId) {
      res.status(400).json({ success: false, error: 'Missing required field: previewSessionId' });
      return;
    }
    if (typeof chatSessionId !== 'string' || !chatSessionId) {
      res.status(400).json({ success: false, error: 'Missing required field: chatSessionId' });
      return;
    }

    // 1. Verify preview session ownership and resolve projectId
    const sessionService = getPreviewSessionService();
    if (!sessionService.isSessionOwned(previewSessionId, userId)) {
      // Distinguish between "doesn't exist" and "not yours"
      const exists = !!sessionService.getSession(previewSessionId);
      res.status(exists ? 403 : 404).json({
        success: false,
        error: exists ? 'Preview session is not owned by user' : 'Preview session not found',
      });
      return;
    }
    const session = sessionService.getSession(previewSessionId);
    const projectId = session?.projectId;
    if (!projectId) {
      // Should never happen — sessions always have a projectId — but be defensive
      res.status(500).json({
        success: false,
        error: 'Preview session is missing project context',
      });
      return;
    }

    // 2. Pre-check ownership without consuming, so a request from the wrong
    //    user can never even temporarily evict the legitimate owner's draft
    //    (matters in shared workspace + shared chat session scenarios).
    const peeked = DraftStepsCache.get(chatSessionId);
    if (!peeked) {
      res.status(404).json({
        success: false,
        error: 'Draft steps are no longer available — please re-run them and try again',
      });
      return;
    }
    if (peeked.userId !== userId) {
      res.status(403).json({
        success: false,
        error: 'Cached draft steps belong to a different user',
      });
      return;
    }

    // 3. Atomically claim. consume() returns the entry AND removes it from
    //    the map in one synchronous step — defends against the race where
    //    two parallel "save" clicks both create duplicate test cases.
    //    On failure below, we re-insert the entry so the user can retry.
    const cached = DraftStepsCache.consume(chatSessionId);
    if (!cached) {
      // Lost the race against a concurrent save — the other request already
      // consumed and is creating the test case right now.
      res.status(409).json({
        success: false,
        error: 'Draft is being saved by another request — refresh in a moment',
      });
      return;
    }

    if (!Array.isArray(cached.steps) || cached.steps.length === 0) {
      // Empty cache entry is a corruption case — don't restore, just fail.
      res.status(400).json({
        success: false,
        error: 'Cached draft has no steps to save',
      });
      return;
    }

    // 4. Resolve the final name via the waterfall
    const finalName = resolveTestCaseName(
      typeof nameOverride === 'string' ? nameOverride : undefined,
      cached.suggestedName,
      cached.steps,
    );

    logger.info('[DRAFT_CONTROLLER] Saving draft as test case', {
      userId,
      projectId,
      previewSessionId,
      chatSessionId,
      stepCount: cached.steps.length,
      nameSource: nameOverride ? 'override' : cached.suggestedName ? 'ai_suggested' : 'derived',
      name: finalName,
    });

    // 5. Persist via the same service the LLM tool uses — ensures both paths
    //    end up with identical DB shape, hooks, validation, etc.
    let createdTestCase;
    try {
      createdTestCase = await IntentTestCaseService.create({
        projectId,
        userId,
        name: finalName,
        startUrl: cached.startUrl,
        steps: cached.steps,
        status: 'draft',
      });
    } catch (createErr) {
      logger.error('[DRAFT_CONTROLLER] IntentTestCaseService.create failed', {
        error: createErr instanceof Error ? createErr.message : String(createErr),
        userId,
        projectId,
        chatSessionId,
      });
      // Restore the cache entry so the user can retry without losing their draft.
      // Note: this resets the createdAt timestamp, effectively giving the user
      // a fresh 30-min TTL after a failed save attempt — acceptable.
      DraftStepsCache.set(chatSessionId, {
        steps: cached.steps,
        startUrl: cached.startUrl,
        userId: cached.userId,
        ...(cached.suggestedName ? { suggestedName: cached.suggestedName } : {}),
      });
      res.status(500).json({
        success: false,
        error: createErr instanceof Error ? createErr.message : 'Failed to create test case',
      });
      return;
    }

    // Cache already removed by consume() above — no further cleanup needed.

    res.json({
      success: true,
      testCase: {
        id: createdTestCase.id,
        name: createdTestCase.name,
      },
    });
  } catch (err) {
    logger.error('[DRAFT_CONTROLLER] saveDraftRunAsTestCase unexpected error', {
      error: err instanceof Error ? err.message : String(err),
    });
    res.status(500).json({
      success: false,
      error: err instanceof Error ? err.message : 'Internal server error',
    });
  }
}
